const input=$input.first().json;const job=input.job??input;
if(job.kind!=='generate_rrss'||!job.id||!job.client_id||!job.target_id||!job.leaseToken)throw new Error('Contrato generate_rrss v1 invalido');
const accounts=job.payload?.accounts;
if(!Array.isArray(accounts)||!accounts.length||accounts.some((account)=>!account?.id))throw new Error('Contrato generate_rrss v1 invalido: payload.accounts no puede estar vacio');
if(!String(job.payload?.planItem?.title??'').trim())throw new Error('Contrato generate_rrss v1 invalido: falta payload.planItem.title');
return [{json:{job}}];

// Shared by every client: brand data comes from editorial_config, the idea and the target accounts from the job.
const job=$('Validar trabajo').first().json.job;
const ctx=$input.first().json;
const cfg=ctx.settings?.editorial_config??{};
const text=(value)=>(value===undefined||value===null?'':String(value).trim());
const NETWORKS=['gmb','facebook','instagram'];
const networkOf=(account)=>{const network=text(account?.network).toLowerCase();return NETWORKS.includes(network)?network:'other';};
const brandName=text(cfg.brandName)||text(cfg.topic);
if(!brandName)throw new Error('Falta editorial_config.brandName para este cliente');
const item=job.payload.planItem;
const keywords=Array.isArray(item.keywords)?item.keywords.map((keyword)=>text(keyword)).filter(Boolean):[];
return [{json:{
  brandName,
  sector:text(cfg.topic),
  siteUrl:(text(cfg.siteUrl)||text(cfg.site_url)).replace(/\/+$/,''),
  title:text(item.title),
  theme:text(item.theme),
  rationale:text(item.rationale),
  format:text(item.format)||'post',
  keywords:keywords.join(', '),
  cta:text(item.cta),
  networks:[...new Set(job.payload.accounts.map(networkOf))],
}}];

