const prepared=$('Preparar posts').first().json;
let text=String($input.first()?.json?.text??'').replace(/```json\s*/gi,'').replace(/```/g,'').trim();
const start=text.indexOf('{');const end=text.lastIndexOf('}');
if(start>=0&&end>start)text=text.slice(start,end+1);
let parsed;
try{parsed=JSON.parse(text);}catch(e){throw new Error('La IA no devolvio un JSON valido de textos por red: '+e.message);}
const texts={};
for(const network of prepared.networks){
  const copy=parsed?.[network];
  if(typeof copy!=='string'||!copy.trim())throw new Error('La IA no devolvio el texto para la red '+network);
  texts[network]=copy.trim();
}
return [{json:{texts}}];

const job=$('Validar trabajo').first().json.job;
const texts=$input.first().json.texts??{};
const NETWORKS=['gmb','facebook','instagram'];
return job.payload.accounts.map((account,index)=>{
  const raw=String(account.network??'').trim().toLowerCase();
  const network=NETWORKS.includes(raw)?raw:'other';
  const copy=texts[network];
  if(!copy)throw new Error('Falta el texto del post para la red '+network);
  return {json:{index,accountId:account.id,network,label:account.label??null,copy}};
});

// 'Recorrer cuentas' (batch size 1) runs this node exactly once per account, so $runIndex is the account's
// position in 'Un item por cuenta'. Items coming from the image chain have lost the account fields (the OpenAI
// and Postiz nodes replace the JSON) and paired-item lookups through the community Postiz node are not reliable,
// so the account is taken from the item when present (skipped-image branch) and by run index otherwise.
const accounts=$('Un item por cuenta').all();
const current=$input.first()?.json??{};
const accountId=typeof current.accountId==='string'?current.accountId:(accounts[$runIndex]?.json?.accountId??null);
// Any image failure (OpenAI, conversion or Postiz upload) degrades to a post without media.
let mediaUrl=null;
try{const path=!current.error&&typeof current.path==='string'?current.path.trim():'';if(/^https?:\/\//i.test(path))mediaUrl=path;}catch(e){mediaUrl=null;}
return [{json:{accountId,mediaUrl}}];

// One post per account from 'Un item por cuenta' (the authoritative list), with the image each loop iteration produced.
const accounts=$('Un item por cuenta').all().map((item)=>item.json);
const media=new Map();
for(const item of $input.all()){const result=item.json??{};if(result.accountId&&result.mediaUrl)media.set(result.accountId,result.mediaUrl);}
const socialPosts=accounts.map((account)=>({accountId:account.accountId,copy:account.copy,media:media.has(account.accountId)?[{url:media.get(account.accountId)}]:[]}));
return [{json:{socialPosts,imagesGenerated:socialPosts.filter((post)=>post.media.length).length}}];

const job=$('Validar trabajo').first().json.job;
const aggregated=$('Agregar posts').first().json;
const selected=new Set((job.payload.accounts??[]).map((account)=>account.id));
const socialPosts=aggregated.socialPosts??[];
if(!socialPosts.length)throw new Error('No hay posts que guardar');
for(const post of socialPosts){
  if(!selected.has(post.accountId))throw new Error('El post pertenece a una cuenta no seleccionada: '+post.accountId);
  if(typeof post.copy!=='string'||!post.copy.trim())throw new Error('Falta el texto del post para la cuenta '+post.accountId);
}
return [{json:{
  schemaVersion:1,
  clientId:job.client_id,
  status:'succeeded',
  socialPosts:socialPosts.map((post)=>({accountId:post.accountId,copy:post.copy,media:Array.isArray(post.media)?post.media:[]})),
  result:{workflowVersion:1,count:socialPosts.length,imagesGenerated:aggregated.imagesGenerated??0,generateImage:job.payload.generateImage!==false},
  leaseToken:job.leaseToken,
  jobId:job.id,
}}];
